task min_Num(s: seq, n: int) returns (r: int)
  requires n >= 0
  ensures r >= 0
  ensures (sum(s) + r) % 2 == 0
{
  var sum: int := 0;
  i := 0;
  while i < len(s)
    invariant 0 <= i and i <= len(s)
    invariant sum == sum(s[0..i])
    decreases len(s) - i
  {
    sum := sum + s[i];
    i := i + 1;
  }
  if sum % 2 == 0 {
    r := 0;
  } else {
    r := 1;
  }
}
